16	
17	    public void service(@Val OwnerFieldsDto request) throws InvalidTelephoneException {
18	        String digits = request.getTelephone().replaceAll("\\D", "");
19	        if (digits.length() != 10) {
20	            throw new InvalidTelephoneException(
21	                    "Telephone must be exactly 10 digits after removing non-digit characters");
22	        }
23	        request.setTelephone(digits);
24	    }
25	}
