1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import net.officefloor.plugin.variable.Val;
4	import org.springframework.samples.petclinic.model.Owner;
5	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
6	import org.springframework.samples.petclinic.rest.escalation.DuplicateTelephoneException;
7	import org.springframework.samples.petclinic.repository.OwnerRepository;
8	
9	/**
10	 * Rejects a create-owner request whose normalized telephone is already used by another
11	 * owner. Runs after {@link NormalizeOwnerTelephone} (so the body carries the stripped
12	 * 10-digit value) and before {@link BuildOwner}, comparing against the normalized
13	 * telephone of every existing owner. A collision is rejected 409 via
14	 * {@link DuplicateTelephoneException}.
15	 */
16	public class RejectDuplicateTelephone {
17	
18	    public void service(@Val OwnerFieldsDto request, OwnerRepository ownerRepository)
19	            throws DuplicateTelephoneException {
20	        String telephone = request.getTelephone();
21	        for (Owner existing : ownerRepository.findAll()) {
22	            if (existing.getTelephone() != null
23	                    && telephone.equals(existing.getTelephone().replaceAll("\\D", ""))) {
24	                throw new DuplicateTelephoneException(
25	                        "Telephone is already used by another owner");
26	            }
27	        }
28	    }
29	}
