16	package org.springframework.samples.petclinic.model;
17	
18	import org.springframework.core.style.ToStringCreator;
19	
20	import jakarta.persistence.*;
21	import jakarta.validation.constraints.Digits;
22	import jakarta.validation.constraints.NotEmpty;
23	import jakarta.validation.constraints.Pattern;
24	
25	import java.util.*;
26	
27	/**
28	 * Simple JavaBean domain object representing an owner.
29	 *
30	 * @author Ken Krebs
31	 * @author Juergen Hoeller
32	 * @author Sam Brannen
33	 * @author Michael Isvy
34	 */
35	@Entity
36	@Table(name = "owners")
37	public class Owner extends Person {
38	    @Column(name = "address")
39	    @NotEmpty
40	    private String address;
41	
42	    @Column(name = "city")
43	    @NotEmpty
44	    private String city;
45	
46	    @Column(name = "telephone")
47	    @NotEmpty
48	    @Digits(fraction = 0, integer = 10)
49	    @Pattern(regexp = "^[0-9]{10}$", message = "Phone number must be exactly 10 digits")
50	    private String telephone;
51	
52	    @Column(name = "email")
53	    private String email;
54	
55	    @Column(name = "registration_date")
56	    private java.time.LocalDate registrationDate;
57	
58	    @OneToMany(cascade = CascadeType.ALL, mappedBy = "owner", fetch = FetchType.EAGER)
59	    private Set<Pet> pets;
60	
61	    public String getAddress() {
62	        return this.address;
63	    }
64	
65	    public void setAddress(String address) {
66	        this.address = address;
67	    }
68	
69	    public String getCity() {
70	        return this.city;
71	    }
72	
73	    public void setCity(String city) {
74	        this.city = city;
75	    }
76	
77	    public String getTelephone() {
78	        return this.telephone;
79	    }
80	
81	    public void setTelephone(String telephone) {
82	        this.telephone = telephone;
83	    }
84	
85	    public String getEmail() {
86	        return this.email;
87	    }
88	
89	    public void setEmail(String email) {
90	        this.email = email;
91	    }
92	
93	    public java.time.LocalDate getRegistrationDate() {
94	        return this.registrationDate;
95	    }
96	
97	    public void setRegistrationDate(java.time.LocalDate registrationDate) {
98	        this.registrationDate = registrationDate;
99	    }
100	
101	    protected Set<Pet> getPetsInternal() {
102	        if (this.pets == null) {
103	            this.pets = new HashSet<>();
104	        }
105	        return this.pets;
106	    }
107	
108	    protected void setPetsInternal(Set<Pet> pets) {
109	        this.pets = pets;
110	    }
111	
112	    public List<Pet> getPets() {
113	        List<Pet> sortedPets = new ArrayList<>(getPetsInternal());
114	        sortedPets.sort(Comparator.comparing(Pet::getName, String.CASE_INSENSITIVE_ORDER));
115	        return Collections.unmodifiableList(sortedPets);
116	    }
117	
118	    public void setPets(List<Pet> pets) {
119	        this.pets = new HashSet<>(pets);
120	    }
121	
122	    public void addPet(Pet pet) {
123	        getPetsInternal().add(pet);
124	        pet.setOwner(this);
125	    }
126	
127	    /**
128	     * Return the Pet with the given name, or null if none found for this Owner.
129	     *
130	     * @param name to test
131	     * @return true if pet name is already in use
132	     */
133	    public Pet getPet(String name) {
134	        return getPet(name, false);
135	    }
136	
137	    /**
138	     * Return the Pet with the given name, or null if none found for this Owner.
139	     *
140	     * @param name to test
141	     * @return true if pet name is already in use
142	     */
143	    public Pet getPet(String name, boolean ignoreNew) {
144	        name = name.toLowerCase();
145	        for (Pet pet : getPetsInternal()) {
146	            if (!ignoreNew || !pet.isNew()) {
147	                String compName = pet.getName();
148	                compName = compName.toLowerCase();
149	                if (compName.equals(name)) {
150	                    return pet;
151	                }
152	            }
153	        }
154	        return null;
155	    }
156	
157	    public Pet getPet(Integer petId) {
158	        return getPetsInternal().stream().filter(p -> p.getId().equals(petId)).findFirst().orElse(null);
159	    }
160	
161	    @Override
162	    public String toString() {
163	        return new ToStringCreator(this)
164	
165	            .append("id", this.getId())
166	            .append("new", this.isNew())
167	            .append("lastName", this.getLastName())
168	            .append("firstName", this.getFirstName())
169	            .append("address", this.address)
170	            .append("city", this.city)
171	            .append("telephone", this.telephone)
172	            .toString();
173	    }
174	}
