package org.springframework.samples.petclinic.rest.function.owner;

import net.officefloor.plugin.variable.Val;
import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
import org.springframework.samples.petclinic.rest.escalation.InvalidTelephoneException;

/**
 * Normalizes the create-owner telephone into E.164 form: a leading '+' and country code
 * are kept when present, otherwise country code '+61' is assumed and a single leading '0'
 * is dropped from the national digits. Spaces, dashes and brackets (indeed every non-digit
 * character) are stripped, and the result must carry 8 to 15 digits after the '+'. Runs
 * after {@link RequireOwnerFields} (so the field is present) and before {@link BuildOwner},
 * mutating the published body in place so the mapped
 * {@link org.springframework.samples.petclinic.model.Owner} — and the response — carries
 * the E.164 value. A telephone that cannot form valid E.164 is rejected 400 via
 * {@link InvalidTelephoneException}.
 */
public class NormalizeOwnerTelephone {

    public void service(@Val OwnerFieldsDto request) throws InvalidTelephoneException {
        request.setTelephone(toE164(request.getTelephone()));
    }

    /**
     * Converts a raw telephone into E.164 form ('+' followed by 8 to 15 digits).
     *
     * @throws InvalidTelephoneException if the input cannot form valid E.164.
     */
    public static String toE164(String raw) throws InvalidTelephoneException {
        if (raw == null) {
            throw new InvalidTelephoneException("Telephone is required");
        }
        boolean hasCountryCode = raw.trim().startsWith("+");
        String digits = raw.replaceAll("\\D", "");
        if (!hasCountryCode) {
            if (digits.startsWith("0")) {
                digits = digits.substring(1);
            }
            digits = "61" + digits;
        }
        if (digits.length() < 8 || digits.length() > 15) {
            throw new InvalidTelephoneException(
                    "Telephone must have 8 to 15 digits in E.164 form");
        }
        return "+" + digits;
    }
}

